<?php declare(strict_types=1); $e=static fn(mixed $v): string => htmlspecialchars((string)$v, ENT_QUOTES, "UTF-8"); ?><style>.cr-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px}.cr-stat{padding:22px;border-radius:14px}.cr-stat .n{font-size:30px;font-weight:700}.cr-muted{color:#667085}.cr-actions{display:flex;gap:8px;flex-wrap:wrap}.cr-badge{display:inline-block;padding:5px 9px;border-radius:999px;font-size:12px;background:#eef2f6}@media(max-width:900px){.cr-grid{grid-template-columns:1fr}.form-grid{grid-template-columns:1fr!important}}</style><div class="page-header"><div><h1><?= $e($record['business_name'] ?? 'Rental Provider') ?></h1><p>Provider details and service coverage.</p></div><div class="page-actions"><a class="btn btn-secondary" href="<?= config('app.base_path') ?>/commercial-rentals/providers">Back</a><a class="btn btn-primary" href="<?= config('app.base_path') ?>/commercial-rentals/providers/<?= (int)$record['id'] ?>/edit">Edit</a></div></div><div class="card"><table class="table"><tbody><?php foreach(['business_name'=>'Business Name','legal_name'=>'Legal Name','phone'=>'Phone','email'=>'Email','address'=>'Address','city'=>'City / Town','district'=>'District','state'=>'State','postal_code'=>'Postal Code','latitude'=>'Latitude','longitude'=>'Longitude','service_areas'=>'Service Areas','description'=>'Description','status'=>'Status','uuid'=>'UUID'] as $key=>$label): ?><tr><th><?= $e($label) ?></th><td><?= nl2br($e($record[$key] ?? '—')) ?></td></tr><?php endforeach; ?></tbody></table></div>
